global.R
ulSort = function(inputId, list.items) {
  children.li <http://children.li/> = NULL
  for(i in 1:length(list.items)) {
    children.li <http://children.li/>[[i]] = tags$li(class="ui-state-default",list.items[[i]])
  }
  tagList(
    tagAppendChildren(tags$ul(id=inputId,
                              class="sortable"),
                      children.li <http://children.li/>)

  )
}

